<?phpnamespace app\api\controller\exchange;use app\api\controller\Controller;use app\api\model\exchange\Goods as GoodsModel;/** * 首页控制器 */class Index extends Controller{    /**     * 获取首页数据     */    public function index()    {        $model = new GoodsModel;        $goods = $model->indexList(10,10);//获取10条商品记录        $coupon = $model->indexList(20,4);//获取4条优惠券记录        return $this->renderSuccess(compact('goods','coupon'));    }         /**     * 分类获取     */    public function lists(int $goods_type = 0,string $search = '')    {        $model = new GoodsModel;        $list = $model->getList($goods_type,$search);        return $this->renderSuccess($list);    }}